/** Мутация по броску d100 (бросок может выходить за 1-100 из-за Inf.b). */
export function mutationByRoll(roll) {
  const r = Number(roll) || 0;
  const row = MUTATION_TABLE.find(([lo, hi]) => r >= lo && r <= hi);
  if (row) return row[2];
  // За границами таблицы — крайние записи.
  return r < MUTATION_TABLE[0][0]
    ? MUTATION_TABLE[0][2]
    : MUTATION_TABLE[MUTATION_TABLE.length - 1][2];
}

